import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int n = Integer.parseInt(line.trim());long sum = 0;StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {if (st.hasMoreTokens()) {sum += Long.parseLong(st.nextToken());}}System.out.println(sum);}}